/**
 * R-1847 — the partners register (firm_partners) and its three RPCs
 * (migration 20261024190000_r1847_firm_partners.sql). Writes only through the RPCs, which
 * check the role, the company and the business type (Partnership / LLP).
 *
 * Read and written through an untyped client: the table and functions are newer than
 * database.types.ts (shared, regenerated by the manager after the migration lands).
 */
"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { SupabaseClient } from "@supabase/supabase-js";
import { toast } from "sonner";

import { createClient } from "@/lib/supabase/client";
import { useCurrentUser } from "@/lib/hooks/useCurrentUser";
import { toastError } from "@/lib/errors/toast-error";
import type { FirmPartner, PartnerSaveInput } from "@/lib/accounting/partners";
import { OWNER_EQUITY_KEY } from "./owner-equity";

const untyped = () => createClient() as unknown as SupabaseClient;

export const FIRM_PARTNERS_KEY = ["firm_partners"] as const;

/**
 * The table is not there yet (code deployed before migration 20261024190000): no partners to
 * show, so the screens still work — every other failed read stays an error.
 */
export function isFirmPartnersTableMissing(err: unknown): boolean {
  const m = err instanceof Error ? err.message : String(err ?? "");
  return /firm_partners/.test(m) && /(does not exist|could not find|schema cache)/i.test(m);
}

/** Every partner of the company (current and former), by name. A failed read is an error. */
export function useFirmPartners(enabled = true) {
  const me = useCurrentUser();
  const tenantId = me.data?.tenantId ?? null;
  return useQuery({
    queryKey: [...FIRM_PARTNERS_KEY, tenantId],
    enabled: enabled && Boolean(tenantId),
    queryFn: async (): Promise<FirmPartner[]> => {
      const { data, error } = await untyped()
        .from("firm_partners")
        .select("id, name, pan, din_dpin, is_designated, profit_share_pct, capital_contribution, joined_on, left_on, note")
        .order("name", { ascending: true });
      if (error) {
        if (isFirmPartnersTableMissing(error.message)) return [];
        throw new Error(error.message);
      }
      return ((data ?? []) as FirmPartner[]).map((p) => ({
        ...p,
        profit_share_pct: Number(p.profit_share_pct),
        capital_contribution: Number(p.capital_contribution),
      }));
    },
  });
}

function invalidateAll(qc: ReturnType<typeof useQueryClient>) {
  qc.invalidateQueries({ queryKey: FIRM_PARTNERS_KEY });
  qc.invalidateQueries({ queryKey: OWNER_EQUITY_KEY });
  qc.invalidateQueries({ queryKey: ["balance-sheet"] });
}

export function useSaveFirmPartner() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: PartnerSaveInput & { id: string | null; is_designated: boolean; note: string | null }) => {
      const { data, error } = await untyped().rpc("save_firm_partner", {
        p_id: input.id,
        p_name: input.name,
        p_pan: input.pan,
        p_din_dpin: input.din_dpin,
        p_is_designated: input.is_designated,
        p_profit_share_pct: input.profit_share_pct,
        p_capital_contribution: input.capital_contribution,
        p_joined_on: input.joined_on,
        p_left_on: input.left_on,
        p_note: input.note,
      });
      if (error) throw new Error(error.message);
      return data as string;
    },
    onSuccess: (_d, input) => {
      invalidateAll(qc);
      toast.success(input.id ? `${input.name} updated` : `${input.name} added to the partners register`);
    },
    onError: (err) => toastError(err, { fallback: "Couldn't save the partner" }),
  });
}

export function useDeleteFirmPartner() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await untyped().rpc("delete_firm_partner", { p_id: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      invalidateAll(qc);
      toast.success("Partner removed");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't remove the partner" }),
  });
}

/** An older drawings / capital entry with a typed name → a register partner. Its stored name stays. */
export function useLinkOwnerEquityPartner() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: { movementId: string; partnerId: string }) => {
      const { error } = await untyped().rpc("link_owner_equity_partner", {
        p_movement_id: input.movementId,
        p_partner_id: input.partnerId,
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      invalidateAll(qc);
      toast.success("Entry linked to the partner");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't link the entry" }),
  });
}
